    inside_title: 'What is happening inside?',
    inside_1: 'pH counts H⁺ ions. pH = −log₁₀[H⁺]: pH 2 means 0.01 mol of H⁺ per litre, pH 3 means 0.001. So pH 2 is 10 times more acidic than pH 3.',
    inside_2: 'Indicators are dyes that have one colour in acid and another in base. Each one switches colour over its own pH range: litmus around 5 to 8, phenolphthalein from 8.2, methyl orange below 4.4.',
    inside_3: 'In the neutralisation lab, the app counts moles: n = concentration × volume. The H⁺ left over (or the OH⁻ left over) is spread over the total volume, and that gives the pH. When they are equal, only water and salt remain: pH 7.',
