    how2: 'ସୂଚକ ଲ୍ୟାବ୍: ସୂଚକରେ ଟ୍ୟାପ୍ କରିବା ପୂର୍ବରୁ ରଙ୍ଗ ଅନୁମାନ କରନ୍ତୁ। ପରେ ଯୋଡ଼ିରେ ରଙ୍ଗ ଖେଳ ଖେଳି ସ୍କୋର ତୁଳନା କରନ୍ତୁ।',
    how3: 'ପ୍ରଶମନ: 20 mL ପର୍ୟ୍ୟନ୍ତ 5 mL କରି ମିଶାନ୍ତୁ, ପରେ ଏକ ଏକ ବୁନ୍ଦା। 25 mL ପାଖରେ pH କେତେ ଶୀଘ୍ର ଡେଇଁପଡ଼େ ଦେଖନ୍ତୁ। ଅମ୍ଳର ଗାଢ଼ତା ବଦଳାଇ ପ୍ରଥମେ ନୂଆ ଶେଷ ବିନ୍ଦୁ ଅନୁମାନ କରନ୍ତୁ।',
    how4: 'ଶ୍ରେଣୀ କାର୍ୟ୍ୟ: ମନ୍ଦାର ଫୁଲ ପାଖୁଡ଼ା ବା ଲାଲ ବନ୍ଧାକୋବି ଉଷୁମ ପାଣିରେ ଭିଜାଇ ନିଜ ସୂଚକ ତିଆରି କରନ୍ତୁ। ଲେମ୍ବୁ ରସ, ସାବୁନ, ବେକିଂ ସୋଡା, କ୍ଷୀର ଓ ଲୁଣ ପାଣି ପରୀକ୍ଷା କରି ଆପ୍ ସହ ତୁଳନା କରନ୍ତୁ।',
    how5: 'ପରୀକ୍ଷା ପୂର୍ବରୁ: ଏକ ପୃଷ୍ଠା ସାରାଂଶ ପ୍ରିଣ୍ଟ କରନ୍ତୁ ଓ 15 ରୁ 15 ନ ପାଇବା ପର୍ୟ୍ୟନ୍ତ କୁଇଜ୍ ଖେଳନ୍ତୁ।'
