    sum_title: 'ఆమ్లాలు, క్షారాలు & pH: ఒక పేజీ సారాంశం',
    sum_name: 'పేరు: ____________________   తరగతి: ________',
    sum_def_acid: 'ఆమ్లం: పుల్లని రుచి, నీలి లిట్మస్‌ను ఎరుపు చేస్తుంది, నీటిలో H⁺ అయాన్లు ఇస్తుంది, pH 7 కన్నా తక్కువ. ఉదా: నిమ్మరసం, వెనిగర్, HCl.',
    sum_def_base: 'క్షారం: చేదు రుచి, సబ్బులా జారుడు, ఎరుపు లిట్మస్‌ను నీలం చేస్తుంది, నీటిలో OH⁻ అయాన్లు ఇస్తుంది, pH 7 కన్నా ఎక్కువ. ఉదా: సబ్బు, బేకింగ్ సోడా, NaOH.',
    sum_def_ph: 'pH: ద్రావణం ఎంత ఆమ్లమో లేదా క్షారమో చెప్పే 0 నుండి 14 వరకు సంఖ్య. 7 తటస్థం. ప్రతి మెట్టు 10 రెట్లు ఎక్కువ లేదా తక్కువ H⁺ అయాన్లు.',
    sum_scale: 'రోజువారీ వస్తువులతో pH స్కేలు',
    sum_ind: 'సూచికలు',
    sum_neut: 'తటస్థీకరణ',
    sum_neut_text: 'ఆమ్లం + క్షారం → లవణం + నీరు. ఉదా: HCl + NaOH → NaCl + H₂O. H⁺, OH⁻ సమాన మోల్‌లు pH 7 ఇస్తాయి. 25 mL 0.1 M HCl కి సరిగ్గా 25 mL 0.1 M NaOH కావాలి.',
    sum_salts: 'లవణాలు: బలమైన తల్లిదండ్రి గెలుస్తుంది',
    sum_life: 'రోజువారీ జీవితంలో pH',
