    inside_title: 'లోపల ఏమి జరుగుతోంది?',
    inside_1: 'pH H⁺ అయాన్లను లెక్కిస్తుంది. pH = −log₁₀[H⁺]: pH 2 అంటే లీటరుకు 0.01 మోల్ H⁺, pH 3 అంటే 0.001. కనుక pH 2, pH 3 కంటే 10 రెట్లు ఎక్కువ ఆమ్లం.',
    inside_2: 'సూచికలు ఆమ్లంలో ఒక రంగు, క్షారంలో మరో రంగు ఉండే రంజకాలు. ప్రతి ఒక్కటి తన pH పరిధిలో రంగు మారుతుంది: లిట్మస్ సుమారు 5 నుండి 8, ఫినాఫ్తలీన్ 8.2 నుండి, మిథైల్ ఆరెంజ్ 4.4 కింద.',
    inside_3: 'తటస్థీకరణ ల్యాబ్‌లో యాప్ మోల్‌లు లెక్కిస్తుంది: n = గాఢత × ఘనపరిమాణం. మిగిలిన H⁺ (లేదా మిగిలిన OH⁻) మొత్తం ఘనపరిమాణంలో వ్యాపిస్తుంది, దాని నుండి pH వస్తుంది. రెండూ సమానమైతే నీరు, లవణం మాత్రమే మిగులుతాయి: pH 7.',
    inside_4: 'అన్ని విలువలు 25 °C వద్ద పాఠ్యపుస్తక సుమారు విలువలు. నిజమైన నిమ్మరసం లేదా సబ్బులో ఈ సంఖ్యలు కొద్దిగా వేరుగా ఉండవచ్చు.',
