    salts_rule: 'ನಿಯಮ: ಪ್ರಬಲ ಪೋಷಕ ಗೆಲ್ಲುತ್ತದೆ. ಪ್ರಬಲ ಆಮ್ಲ + ಪ್ರಬಲ ಪ್ರತ್ಯಾಮ್ಲ → ತಟಸ್ಥ ಲವಣ. ಪ್ರಬಲ ಆಮ್ಲ + ದುರ್ಬಲ ಪ್ರತ್ಯಾಮ್ಲ → ಆಮ್ಲೀಯ ಲವಣ. ದುರ್ಬಲ ಆಮ್ಲ + ಪ್ರಬಲ ಪ್ರತ್ಯಾಮ್ಲ → ಪ್ರತ್ಯಾಮ್ಲೀಯ ಲವಣ.',
